mapper.update:
UPDATE product
SET stock = stock - #{quantity},
    sales = sales + #{quantity},
    version = version + 1,
    update_time = NOW()
WHERE id = #{productId}
  AND version = #{version}
  AND deleted = 0
  AND stock >= #{quantity}

mapper.select:
SELECT p.id, p.name, p.subtitle, p.main_image, p.price, p.original_price, p.stock, p.sales, p.status, p.sort_order, p.create_time, p.merchant_id, m.shop_name AS shop_name FROM product p LEFT JOIN merchant m ON p.merchant_id = m.id AND m.deleted = 0
p.deleted = 0
AND p.name LIKE CONCAT('%', #{params.name}, '%')
AND p.merchant_id = #{params.merchantId}
AND p.status = #{params.status}
AND p.category_id = #{params.categoryId}
AND p.category_id IN (SELECT id FROM category WHERE parent_id = #{params.parentCategoryId} AND deleted = 0)
ORDER BY p.sort_order DESC, p.create_time DESC
